import sys, os, json, csv, io, re


def norm_id(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = str(s).casefold()
    s = ''.join(c if c.isalnum() else ' ' for c in s)
    return ' '.join(s.split())


def parse_csv(text):
    lines = text.split('\n')
    meta = {}
    i = 0
    while i < len(lines):
        ln = lines[i].rstrip('\r')
        if ln.strip() == '':
            i += 1
            continue
        if ln.startswith('#'):
            m = re.match(r'#\s*([^:]*?)\s*:\s*(.*?)\s*$', ln)
            if m:
                meta[m.group(1).strip().lower()] = m.group(2)
            i += 1
            continue
        break
    rest = '\n'.join(lines[i:])
    rows = list(csv.reader(io.StringIO(rest, newline='')))
    rows = [r for r in rows if r and any(c.strip() for c in r)]
    recs = []
    if rows:
        hdr = [h.strip() for h in rows[0]]
        for r in rows[1:]:
            d = dict(zip(hdr, r))
            ranks = {}
            for h in hdr:
                m = re.fullmatch(r'rank(\d+)', h)
                if m and d.get(h, '') != '':
                    marks = []
                    for p in d[h].split('|'):
                        if p.strip() == '':
                            continue
                        ps = p.strip()
                        if ps[:3].upper() == 'WI:':
                            marks.append(('w', ps[3:]))
                        else:
                            marks.append(('c', ps))
                    ranks[int(m.group(1))] = marks
            recs.append((d.get('ballot', ''), d.get('contest', '').strip(), ranks))
    return meta, recs


def parse_jsonl(text):
    meta = None
    recs = []
    for ln in text.split('\n'):
        if not ln.strip():
            continue
        o = json.loads(ln)
        if meta is None:
            meta = {k: o[k] for k in o}
            continue
        ranks = {}
        for mk in o.get('marks', []):
            r = int(mk['rank'])
            lst = ranks.setdefault(r, [])
            if 'write_in' in mk and mk['write_in'] is not None:
                lst.append(('w', mk['write_in']))
            else:
                lst.append(('c', mk['candidate']))
        recs.append((o.get('ballot', ''), str(o.get('contest', '')).strip(), ranks))
    return meta, recs


def main():
    inp, out = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, 'election.json'), encoding='utf-8') as f:
        el = json.load(f)
    cvr = os.path.join(inp, 'cvr')
    batches = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p):
            continue
        if not (name.endswith('.csv') or name.endswith('.jsonl')):
            continue
        with open(p, encoding='utf-8', newline='') as f:
            text = f.read()
        if text.startswith('\ufeff'):
            text = text[1:]
        meta, recs = parse_csv(text) if name.endswith('.csv') else parse_jsonl(text)
        bid = str(meta.get('batch', '')).strip()
        rev = int(str(meta.get('revision', '0')).strip())
        status = str(meta.get('status', 'final')).strip().lower()
        if bid not in batches or rev > batches[bid][0]:
            batches[bid] = (rev, status, recs)
    by_contest = {}
    for rev, status, recs in batches.values():
        if status == 'void':
            continue
        for b, c, ranks in recs:
            by_contest.setdefault(c, []).append(ranks)

    result = {'election': el['election'], 'contests': []}
    for ct in el['contests']:
        result['contests'].append(run_contest(ct, by_contest.get(ct['id'], [])))
    with open(out, 'w', encoding='utf-8') as f:
        json.dump(result, f, ensure_ascii=False, indent=1)


def run_contest(ct, records):
    maxr = ct['max_ranks']
    idmap = {}  # normalized -> output id
    withdrawn = set()
    cont = []
    for c in ct['candidates']:
        n = norm_id(c['id'])
        idmap[n] = c['id']
        if c.get('status') == 'withdrawn':
            withdrawn.add(n)
        else:
            cont.append(n)
    wmap = {}
    for w in ct.get('write_ins', []):
        n = norm_id(w['id'])
        idmap[n] = w['id']
        cont.append(n)
        for t in [w['name']] + list(w.get('aliases', [])):
            wmap[norm_text(t)] = n
    lot = [norm_id(x) for x in ct.get('lot_order', [])]
    lotpos = {n: i for i, n in enumerate(lot)}

    ballots = []
    for ranks in records:
        seen = set()
        rs = []
        for r in range(1, maxr + 1):
            marks = set()
            for kind, v in ranks.get(r, []):
                if kind == 'w':
                    q = wmap.get(norm_text(v))
                    if q is not None:
                        marks.add(q)
                else:
                    marks.add(norm_id(v))
            if not marks:
                rs.append(('skip', None))
                continue
            marks -= withdrawn
            if not marks:
                rs.append(('pass', None))
                continue
            new = marks - seen
            seen |= marks
            if not new:
                rs.append(('skip', None))
            elif len(new) == 1:
                rs.append(('choice', next(iter(new))))
            else:
                rs.append(('over', None))
        ballots.append(rs)

    def read(rs, cs):
        n = len(rs)
        for i, (k, v) in enumerate(rs):
            if k == 'choice':
                if v in cs:
                    return v
            elif k == 'over':
                return None
            elif k == 'skip':
                if i + 1 >= n or rs[i + 1][0] == 'skip':
                    return None
        return None

    cs = set(cont)
    hist = []
    rounds = []
    winner = None
    rn = 0
    while True:
        rn += 1
        t = {c: 0 for c in cs}
        active = 0
        for rs in ballots:
            c = read(rs, cs)
            if c is not None:
                t[c] += 1
                active += 1
        hist.append(t)
        rd = {'round': rn, 'tallies': {idmap[c]: v for c, v in t.items()},
              'exhausted': len(ballots) - active, 'eliminated': []}
        rounds.append(rd)
        if active == 0:
            break
        win = None
        for c, v in t.items():
            if v * 2 > active:
                win = c
        if win is None and len(cs) == 1:
            win = next(iter(cs))
        if win is not None:
            winner = idmap[win]
            break
        zeros = [c for c in cs if t[c] == 0]
        if zeros:
            el = zeros
        else:
            m = min(t.values())
            tied = [c for c in cs if t[c] == m]
            k = rn - 2
            while len(tied) > 1 and k >= 0:
                mm = min(hist[k][c] for c in tied)
                tied = [c for c in tied if hist[k][c] == mm]
                k -= 1
            if len(tied) > 1:
                tied = [max(tied, key=lambda c: lotpos.get(c, -1))]
            el = tied
        rd['eliminated'] = sorted(idmap[c] for c in el)
        cs -= set(el)
    return {'contest': ct['id'], 'ballots': len(ballots), 'winner': winner, 'rounds': rounds}


main()
